/bin/bash -lc "mkdir -p src/util && cat > src/util/ordersApi.mjs <<'EOF'
/**
 * Normalize the backend's order-list response (ReadableOrderList, as returned
 * by GET /auth/orders — the same response RecentOrder.js loads) into a
 * consistent shape.
 *
 * @param {object|undefined|null} response
 * @returns {{orders: Array, pages: number, total: number, onThisPage: number}}
 */
export function normalizeOrderList(response) {
  const data = response && typeof response === 'object' ? response : {};
  return {
    orders: Array.isArray(data.orders) ? data.orders : [],
    pages: Number.isFinite(data.pageCount) ? data.pageCount : 0,
    total: Number.isFinite(data.totalRecords) ? data.totalRecords : 0,
    onThisPage: Number.isFinite(data.itemsOnPage) ? data.itemsOnPage : 0
  };
}
EOF
